541	
542	func TestReloadWorldPreservesTime(t *testing.T) {
543		a, _ := newTestArchive(t)
544		w := baseWorld(t)
545		r0, _ := a.Save("s", w)
546		_, _ = w.Apply(Commit{
547			Moves:       []Move{{Character: "hero", To: "yard"}},
548			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
549			Time:        7,
