210	// 按 encoding/json 的字段选择规则（大小写不敏感、Unicode 转义还原后再比较）
211	// 把顶层键归并到它实际会读取的字段上。
212	var slotPointerFields = []string{"latest", "history"}
213	
214	// checkSlotPointerDuplicateFields 检查槽指针 JSON 顶层对象内是否有两个名称
215	// 会被现有读取方式解释为同一个固定字段 latest 或 history。
216	//
217	// encoding/json 对同名字段静默采用后一个值：同一指针里 "latest" 写两次时
218	// 前一个值会被后一个覆盖，"history" 重复出现时后一份历史会替换前一份，
219	// 于是读到的当前世界或可恢复历史会随字段书写次序变化。出现这种歧义时
220	// 必须明确拒绝整个指针，不能选一个值继续使用。
221	//
222	// 判定与读取方式保持一致：JSON 键先按 Unicode 转义还原，再做大小写不敏感
223	// 比较，因此完全相同的名称、只改变大小写的写法（"Latest" 与 "latest"）
224	// 以及 Unicode 转义还原后对应同一字段的写法（直接写出的 "latest" 与写作转义形式的 "\u006catest"）都算同一字段。只检查指针顶层对象：数组元素与
225	// 嵌套对象中的键不参与，history 数组里同一记录标识出现多次属于另一种情况
226	// （由后续去重处理）。
227	func checkSlotPointerDuplicateFields(data []byte) error {
228		dec := json.NewDecoder(bytes.NewReader(data))
229		dec.UseNumber()
230		// 只遍历顶层对象：读取根 '{'、逐键消费其值（可能是标量或容器），
231		// 遇到根 '}' 即结束。嵌套对象/数组内部的名称不影响指针字段判定。
232		if err := expectPointerToken(dec, '{'); err != nil {
233			return err
234		}
235		seen := make(map[string]bool)
236		for {
237			tok, err := dec.Token()
238			if err != nil {
239				return err
240			}
241			if d, ok := tok.(json.Delim); ok && d == '}' {
242				return nil
243			}
244			key, ok := tok.(string)
245			if !ok {
246				return errSlotPointerDuplicate
247			}
248			identity := slotPointerFieldIdentity(key)
249			if identity != "" {
250				if seen[identity] {
251					return errSlotPointerDuplicate
252				}
253				seen[identity] = true
254			}
255			if err := skipJSONValue(dec); err != nil {
256				return err
257			}
258		}
259	}
260	
261	// errSlotPointerDuplicate 是内部哨兵错误，仅用于区分“字段重复”与遍历
262	// 槽指针令牌时遇到的其它解析问题（后者统一按“无法解析”处理）。
263	var errSlotPointerDuplicate = errors.New("槽指针字段重复")
264	
265	// slotPointerFieldIdentity 返回顶层键 key 会读取到的固定字段名（"latest"
266	// 或 "history"）；键不对应任何登记字段时返回空串。
267	func slotPointerFieldIdentity(key string) string {
268		for _, name := range slotPointerFields {
269			if strings.EqualFold(name, key) {
270				return name
271			}
272		}
273		return ""
274	}
275	
276	// expectPointerToken 从 dec 读取下一个令牌并断言它是 want。
